package com.personal.assistant.module.security.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.personal.assistant.module.security.entity.SecurityAuditLog;import com.personal.assistant.module.security.mapper.SecurityAuditLogMapper;import jakarta.servlet.http.HttpServletRequest;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class SecurityAuditService{private final SecurityAuditLogMapper mapper;public SecurityAuditService(SecurityAuditLogMapper mapper){this.mapper=mapper;}public void record(Long uid,String username,String operation,String resourceType,String resourceId,boolean success,String reason,HttpServletRequest request){SecurityAuditLog x=new SecurityAuditLog();x.setUserId(uid);x.setUsername(username);x.setOperation(operation);x.setResourceType(resourceType);x.setResourceId(resourceId);x.setResult(success?"SUCCESS":"FAILED");x.setFailureReason(reason);x.setOccurredAt(LocalDateTime.now(ZoneId.of("Asia/Shanghai")));if(request!=null){String forwarded=request.getHeader("X-Forwarded-For");x.setIpAddress(forwarded==null?request.getRemoteAddr():forwarded.split(",")[0].trim());x.setUserAgent(request.getHeader("User-Agent"));}mapper.insert(x);}public List<SecurityAuditLog>list(Long uid,String operation,String result){return mapper.selectList(new LambdaQueryWrapper<SecurityAuditLog>().eq(SecurityAuditLog::getUserId,uid).eq(operation!=null,SecurityAuditLog::getOperation,operation).eq(result!=null,SecurityAuditLog::getResult,result).orderByDesc(SecurityAuditLog::getOccurredAt).last("limit 500"));}}
